import type { Metadata } from "next";
import entriesJson from "@/content/entries.json";

// Generated by tools/convert_content.py from the WordPress backup — do not edit entries.json by hand.
export type Entry = {
  id: number;
  kind: "page" | "service" | "post";
  lang: "en" | "ar";
  path: string;
  slug: string;
  title: string;
  date: string;
  modified: string;
  excerpt: string;
  featured: string;
  seo: { title: string; description: string; canonical: string; robots: Record<string, string> };
  html: string;
};

const entries = entriesJson as Entry[];

export const getByPath = (path: string) => entries.find((e) => e.path === path);
export const getById = (id: number) => entries.find((e) => e.id === id);

export const servicesEn = () => entries.filter((e) => e.kind === "service" && e.lang === "en");
export const postsEn = () => entries.filter((e) => e.kind === "post" && e.lang === "en");

/** Old SEO (Yoast) → Next.js metadata, so titles, descriptions and canonicals stay identical. */
export function seoMetadata(e: Entry): Metadata {
  const noindex = e.seo.robots?.index === "noindex";
  return {
    title: e.seo.title || e.title,
    description: e.seo.description || e.excerpt,
    alternates: { canonical: e.seo.canonical || e.path },
    robots: noindex ? { index: false, follow: true } : undefined,
    openGraph: {
      title: e.seo.title || e.title,
      description: e.seo.description || e.excerpt,
      url: e.path,
      type: e.kind === "post" ? "article" : "website",
      images: e.featured ? [e.featured] : ["/images/logo.png"],
    },
  };
}

export const readingMinutes = (html: string) => Math.max(1, Math.round(html.replace(/<[^>]+>/g, " ").split(/\s+/).length / 220));

export const formatDate = (iso: string) => new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
